# Generated by manage.py generate_test_cases.
"""Exercise optional field upload without replacing files or bypassing permissions."""

import base64
from typing import Any
from unittest.mock import patch

from django.http import HttpResponse
from django.test import override_settings
from rest_framework.response import Response
from rest_framework.test import APIRequestFactory, force_authenticate

from bloomerp.filters.definition import FilterCondition
from bloomerp.models import FileNode, FileReference
from bloomerp.permissions.definition import BloomerpPermission, RowPolicyRuleContent
from bloomerp.permissions.manager import PolicyManager
from bloomerp.tests.base import BloomerpAPIViewTestCase, ExpectedResult, RequestScenario
from bloomerp.views.api.files.upload_file import AssistantFileUploadView


class TestAssistantFileUploadView(BloomerpAPIViewTestCase):
    """Cover field upload validation, row-sensitive grants and storage rollback."""

    view_name = "api_assistant_file_upload"
    auto_create_customers = False

    def extendedSetup(self) -> None:
        """Create two targets and a reusable encoded upload using temporary media."""
        self.customer = self.create_customer("Upload", "Target", 30)
        self.other = self.create_customer("Other", "Target", 31)
        self.field = self.CustomerModel._meta.get_field("picture")
        self.data = {
            "filename": "Résumé spaced.txt",
            "content_base64": base64.b64encode(b"resume").decode(),
            "model_label": self.CustomerModel._meta.label,
            "object_id": str(self.customer.pk),
            "field": "picture",
        }

    def file_was_assigned(self, response: HttpResponse) -> bool:
        """Assert returned bytes and a field-specific reference with no generic bypass."""
        payload = response.json()
        file = FileNode.objects.get(pk=payload["file_id"])
        self.assertEqual(file.content.read(), b"resume")
        reference = file.references.get()
        self.assertEqual(reference.application_field.field, "picture")
        self.assertEqual(reference.object_id, str(self.customer.pk))
        self.assertEqual(payload["field"], "picture")
        self.assertEqual(reference.created_by_id, self.admin_user.pk)
        return True

    def no_file_created(self, response: HttpResponse) -> bool:
        """Assert invalid requests created neither records nor field assignments."""
        self.assertFalse(FileNode.objects.exists())
        self.assertFalse(FileReference.objects.exists())
        return True

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Cover routed success and malformed destinations before byte persistence."""
        scenarios = [
            RequestScenario(
                name="Upload directly assigns a BloomerpFileField",
                method="POST",
                user=self.admin_user,
                content_type="application/json",
                data=self.data,
                expected=ExpectedResult(
                    status_code=201, response_validators=self.file_was_assigned
                ),
            )
        ]
        for name, data in [
            ("generic text", {**self.data, "field": "first_name"}),
            ("generic files relation", {**self.data, "field": "files"}),
            ("unknown field", {**self.data, "field": "missing"}),
            ("unknown model", {**self.data, "model_label": "missing.Model"}),
            ("invalid object ID", {**self.data, "object_id": "invalid"}),
            (
                "missing identity",
                {
                    key: value
                    for key, value in self.data.items()
                    if key not in {"model_label", "object_id"}
                },
            ),
            (
                "incomplete identity",
                {key: value for key, value in self.data.items() if key != "object_id"},
            ),
            ("empty bytes", {**self.data, "content_base64": ""}),
        ]:
            scenarios.append(
                RequestScenario(
                    name=f"Reject {name}",
                    method="POST",
                    user=self.admin_user,
                    content_type="application/json",
                    data=data,
                    expected=ExpectedResult(
                        status_code=400, response_validators=self.no_file_created
                    ),
                )
            )
        return scenarios

    def upload(self, data: dict[str, Any] | None = None, user: Any = None) -> Response:
        """Invoke the real upload endpoint for stateful permission and rollback tests."""
        request = APIRequestFactory().post("/", data or self.data, format="json")
        force_authenticate(request, user=user or self.admin_user)
        return AssistantFileUploadView.as_view()(request)

    def grant(self, fields: list[str], permissions: list[BloomerpPermission]) -> Any:
        """Grant a precise row and selected fields to the ordinary user."""
        policy = PolicyManager.create_policy(
            model_or_content_type=self.CustomerModel,
            field_permissions={field: permissions for field in fields},
            row_permissions=[
                RowPolicyRuleContent(
                    permissions=permissions,
                    conditions=[
                        FilterCondition(
                            field_path="id",
                            lookup_id="equals",
                            value=str(self.customer.pk),
                        ),
                    ],
                )
            ],
        )
        policy.users.add(self.normal_user)
        return policy

    def test_single_field_rejects_replacement_without_writes(self) -> None:
        """Keep the existing attachment and avoid writing any bytes on a second upload."""
        first = self.upload()
        self.assertEqual(first.status_code, 201, first.data)
        storage = FileNode._meta.get_field("content").storage
        with patch.object(storage, "save", wraps=storage.save) as save:
            response = self.upload()
        self.assertEqual(response.status_code, 400)
        self.assertIn("already has", str(response.data))
        self.assertEqual(FileNode.objects.count(), 1)
        self.assertEqual(FileReference.objects.count(), 1)
        save.assert_not_called()

    def test_multiple_field_appends_and_enforces_max_files(self) -> None:
        """Retain earlier attachments and reject a count overflow before persistence."""
        with (
            patch.object(self.field, "multiple", True),
            patch.object(self.field, "max_files", 2),
        ):
            first, second = self.upload(), self.upload()
            self.assertEqual(first.status_code, 201, first.data)
            self.assertEqual(second.status_code, 201, second.data)
            self.assertNotEqual(first.data["file_id"], second.data["file_id"])
            self.assertEqual(self.upload().status_code, 400)
        self.assertEqual(FileNode.objects.count(), 2)
        self.assertEqual(FileReference.objects.count(), 2)

    def test_field_extension_size_and_global_limits(self) -> None:
        """Run the owning field's upload validation and shared total-byte validation."""
        for attribute, value in [("allowed_extensions", ["pdf"]), ("max_file_size", 5)]:
            with (
                self.subTest(attribute=attribute),
                patch.object(self.field, attribute, value),
            ):
                self.assertEqual(self.upload().status_code, 400)
        with override_settings(BLOOMERP_AGENT_UPLOAD_MAX_BYTES=5):
            self.assertEqual(self.upload().status_code, 400)
        self.assertFalse(FileNode.objects.exists())
        with patch.object(self.field, "max_file_size", 6):
            self.assertEqual(self.upload().status_code, 201)

    def test_row_and_field_view_change_permissions(self) -> None:
        """Require visibility and change grants for this field on this specific row."""
        permissions = [BloomerpPermission.VIEW, BloomerpPermission.CHANGE]
        policy = self.grant(["files"], permissions)
        self.assertEqual(self.upload(user=self.normal_user).status_code, 403)
        policy.delete()
        policy = self.grant(["picture"], [BloomerpPermission.VIEW])
        self.assertEqual(self.upload(user=self.normal_user).status_code, 403)
        policy.delete()
        self.grant(["picture"], permissions)
        self.assertEqual(
            self.upload(
                {**self.data, "object_id": str(self.other.pk)}, self.normal_user
            ).status_code,
            403,
        )
        response = self.upload(user=self.normal_user)
        self.assertEqual(response.status_code, 201, response.data)
        self.assertEqual(FileNode.objects.count(), 1)

    def test_reference_failure_cleans_storage_and_rolls_back(self) -> None:
        """Remove freshly stored bytes if field reference creation fails."""
        storage = FileNode._meta.get_field("content").storage
        with (
            patch.object(
                FileReference.objects, "create", side_effect=RuntimeError("save failed")
            ),
            patch.object(storage, "delete", wraps=storage.delete) as delete,
            self.assertRaisesRegex(RuntimeError, "save failed"),
        ):
            self.upload()
        self.assertFalse(FileNode.objects.exists())
        self.assertFalse(FileReference.objects.exists())
        delete.assert_called_once()
        self.assertFalse(storage.exists(delete.call_args.args[0]))

    def test_filename_and_base64_bounds_precede_storage(self) -> None:
        """Reject unsafe names and oversized encoded input without decoding or saving."""
        for name in ["../resume.txt", "dir\\resume.txt", "resume\n.txt", ".", ".."]:
            with self.subTest(name=name):
                self.assertEqual(
                    self.upload({**self.data, "filename": name}).status_code, 400
                )
        with (
            override_settings(BLOOMERP_AGENT_UPLOAD_MAX_BYTES=6),
            patch(
                "bloomerp.serializers.assistant_files.base64.b64decode",
                side_effect=AssertionError("Must reject before decoding"),
            ),
        ):
            self.assertEqual(
                self.upload({**self.data, "content_base64": "a" * 12}).status_code, 400
            )
        self.assertFalse(FileNode.objects.exists())
        with override_settings(BLOOMERP_AGENT_UPLOAD_MAX_BYTES=6):
            self.assertEqual(self.upload().status_code, 201)
